#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <hls_math.h>

// Fixed-point type: 46 total bits, 28 fractional bits
typedef ap_fixed<46, 18> fixed_t;

// Complex fixed-point struct
struct complex_t {
    fixed_t re;
    fixed_t im;
};

// Matrix and vector dimensions
static const int N = 10;

// Top-level kernel
void kernel_top(
    complex_t A_in[N][N],
    int       max_iter,
    int      *out_iter,
    complex_t out_eig[N],
    complex_t out_V[N][N]
);

#endif // KERNEL_H
