#include "kernel.h"
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Helper: complex multiply
// ---------------------------------------------------------------------------
static complex_t cmul(complex_t a, complex_t b) {
#pragma HLS INLINE
    complex_t r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: complex conjugate
// ---------------------------------------------------------------------------
static complex_t cconj(complex_t a) {
#pragma HLS INLINE
    complex_t r;
    r.re =  a.re;
    r.im = -a.im;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: magnitude squared of complex number
// ---------------------------------------------------------------------------
static fixed_t cabs2(complex_t a) {
#pragma HLS INLINE
    return a.re * a.re + a.im * a.im;
}

// ---------------------------------------------------------------------------
// Helper: magnitude of complex number
// ---------------------------------------------------------------------------
static fixed_t cabs(complex_t a) {
#pragma HLS INLINE
    fixed_t s = a.re * a.re + a.im * a.im;
    // Use double sqrt via hls_math then cast back
    double sd = (double)s;
    double rd = hls::sqrt(sd);
    return (fixed_t)rd;
}

// ---------------------------------------------------------------------------
// Top-level function
// ---------------------------------------------------------------------------
void kernel_top(
    complex_t A_in[N][N],
    int       max_iter,
    int      *out_iter,
    complex_t out_eig[N],
    complex_t out_V[N][N]
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INTERFACE ap_none    port=max_iter
#pragma HLS INTERFACE ap_none    port=out_iter

    // Working copies of A and V
    complex_t A[N][N];
    complex_t V[N][N];

    // Initialize A from input, V = identity
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=2
            A[i][j] = A_in[i][j];
            V[i][j].re = (i == j) ? (fixed_t)1 : (fixed_t)0;
            V[i][j].im = (fixed_t)0;
        }
    }

    int final_iter = max_iter - 1;

    // Main Jacobi iteration loop
    ITER_LOOP: for (int z = 0; z < max_iter; z++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=2000 avg=500

        // ------------------------------------------------------------------
        // Find off-diagonal element with largest magnitude
        // ------------------------------------------------------------------
        fixed_t off_diag_max = (fixed_t)0;
        int p = 0, q = 1;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
#pragma HLS PIPELINE II=1
                fixed_t mag = cabs(A[i][j]);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // Convergence check: threshold 1e-8
        if (off_diag_max < (fixed_t)1e-8) {
            final_iter = z;
            break;
        }

        // ------------------------------------------------------------------
        // Compute rotation parameters
        // ------------------------------------------------------------------
        complex_t a_pp = A[p][p];
        complex_t a_qq = A[q][q];
        complex_t a_pq = A[p][q];

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        // Note: a_pp and a_qq are real on the diagonal (imaginary should be ~0)
        double a_pq_mag = (double)cabs(a_pq);
        double denom    = (double)(a_pp.re - a_qq.re);
        double theta_d  = 0.5 * hls::atan2(2.0 * a_pq_mag, denom);
        fixed_t cos_t   = (fixed_t)hls::cos(theta_d);
        fixed_t sin_t   = (fixed_t)hls::sin(theta_d);

        // phi = -angle(a_pq) => exp(-j*phi) = a_pq/|a_pq|  (conjugate direction)
        // exp( j*phi) = conj(a_pq)/|a_pq|
        // Guard against zero a_pq
        fixed_t apq_mag_fp = (fixed_t)a_pq_mag;
        complex_t exp_neg_phi; // exp(-j*phi)
        complex_t exp_pos_phi; // exp(+j*phi)
        if (a_pq_mag > 1e-30) {
            // exp(-j*phi) = a_pq  / |a_pq|
            exp_neg_phi.re =  a_pq.re / apq_mag_fp;
            exp_neg_phi.im =  a_pq.im / apq_mag_fp;
            // exp(+j*phi) = conj(a_pq) / |a_pq|
            exp_pos_phi.re =  a_pq.re / apq_mag_fp;
            exp_pos_phi.im = -a_pq.im / apq_mag_fp;
        } else {
            exp_neg_phi.re = (fixed_t)1; exp_neg_phi.im = (fixed_t)0;
            exp_pos_phi.re = (fixed_t)1; exp_pos_phi.im = (fixed_t)0;
        }

        // U entries at (p,p), (p,q), (q,p), (q,q)
        // U[p][p] =  cos(theta)
        // U[p][q] =  sin(theta)*exp(-j*phi)
        // U[q][p] =  sin(theta)*exp(+j*phi)
        // U[q][q] = -cos(theta)
        complex_t U_pp; U_pp.re =  cos_t;    U_pp.im = (fixed_t)0;
        complex_t U_qq; U_qq.re = -cos_t;    U_qq.im = (fixed_t)0;
        complex_t U_pq; U_pq.re = sin_t * exp_neg_phi.re; U_pq.im = sin_t * exp_neg_phi.im;
        complex_t U_qp; U_qp.re = sin_t * exp_pos_phi.re; U_qp.im = sin_t * exp_pos_phi.im;

        // ------------------------------------------------------------------
        // A = U^H * A * U
        // We do this in two passes: A_tmp = U^H * A, then A = A_tmp * U
        // U^H[p][p] = conj(U_pp) =  cos_t
        // U^H[q][q] = conj(U_qq) = -cos_t
        // U^H[p][q] = conj(U_qp)
        // U^H[q][p] = conj(U_pq)
        // ------------------------------------------------------------------
        complex_t Uh_pp = cconj(U_pp);
        complex_t Uh_qq = cconj(U_qq);
        complex_t Uh_pq = cconj(U_qp); // U^H[p][q] = conj(U[q][p])
        complex_t Uh_qp = cconj(U_pq); // U^H[q][p] = conj(U[p][q])

        // Pass 1: B = U^H * A  (only rows p and q change)
        complex_t B[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
                B[i][j] = A[i][j];
            }
        }
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            // new row p: Uh_pp * A[p][j] + Uh_pq * A[q][j]
            complex_t t1 = cmul(Uh_pp, A[p][j]);
            complex_t t2 = cmul(Uh_pq, A[q][j]);
            B[p][j].re = t1.re + t2.re;
            B[p][j].im = t1.im + t2.im;

            // new row q: Uh_qp * A[p][j] + Uh_qq * A[q][j]
            complex_t t3 = cmul(Uh_qp, A[p][j]);
            complex_t t4 = cmul(Uh_qq, A[q][j]);
            B[q][j].re = t3.re + t4.re;
            B[q][j].im = t3.im + t4.im;
        }

        // Pass 2: A = B * U  (only columns p and q change)
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
                A[i][j] = B[i][j];
            }
        }
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            complex_t Bip = B[i][p];
            complex_t Biq = B[i][q];

            // new col p: B[i][p]*U_pp + B[i][q]*U_qp
            complex_t s1 = cmul(Bip, U_pp);
            complex_t s2 = cmul(Biq, U_qp);
            A[i][p].re = s1.re + s2.re;
            A[i][p].im = s1.im + s2.im;

            // new col q: B[i][p]*U_pq + B[i][q]*U_qq
            complex_t s3 = cmul(Bip, U_pq);
            complex_t s4 = cmul(Biq, U_qq);
            A[i][q].re = s3.re + s4.re;
            A[i][q].im = s3.im + s4.im;
        }

        // Zero out off-diagonal pivot elements (enforce symmetry)
        A[p][q].re = (fixed_t)0; A[p][q].im = (fixed_t)0;
        A[q][p].re = (fixed_t)0; A[q][p].im = (fixed_t)0;

        // ------------------------------------------------------------------
        // V = V * U  (only columns p and q change)
        // ------------------------------------------------------------------
        complex_t V_tmp_p[N];
        complex_t V_tmp_q[N];

        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            complex_t vp = V[i][p];
            complex_t vq = V[i][q];

            complex_t r1 = cmul(vp, U_pp);
            complex_t r2 = cmul(vq, U_qp);
            V_tmp_p[i].re = r1.re + r2.re;
            V_tmp_p[i].im = r1.im + r2.im;

            complex_t r3 = cmul(vp, U_pq);
            complex_t r4 = cmul(vq, U_qq);
            V_tmp_q[i].re = r3.re + r4.re;
            V_tmp_q[i].im = r3.im + r4.im;
        }

        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            V[i][p] = V_tmp_p[i];
            V[i][q] = V_tmp_q[i];
        }

        final_iter = z;
    } // end ITER_LOOP

    // ------------------------------------------------------------------
    // Write outputs
    // ------------------------------------------------------------------
    *out_iter = final_iter;

    for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        out_eig[i] = A[i][i];
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS UNROLL factor=2
            out_V[i][j] = V[i][j];
        }
    }
}
