#include <cstdio>
#include <cstdlib>
#include <cstring>
#include "kernel.h"

// ---------------------------------------------------------------------------
// Paths (literal — not computed at runtime)
// ---------------------------------------------------------------------------
static const char IO_DIR[]  = "/home/mbenton/verilog_rapid_prototyping/conversion_012/eig_10_io/";
static const char SIM_DIR[] = "/home/mbenton/verilog_rapid_prototyping/conversion_012/build/sim/";

// ---------------------------------------------------------------------------
// Utility: build a full path from directory + filename
// ---------------------------------------------------------------------------
static void make_path(char *buf, size_t bufsz,
                      const char *dir, const char *fname)
{
    snprintf(buf, bufsz, "%s%s", dir, fname);
}

// ---------------------------------------------------------------------------
// Read helpers
// ---------------------------------------------------------------------------

// Read one int64 scalar from a flat text file (call-index offset by line)
static int read_int_scalar(const char *dir, const char *fname, int call_idx)
{
    char path[512];
    make_path(path, sizeof(path), dir, fname);
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    int val = 0;
    for (int i = 0; i <= call_idx; i++) {
        if (fscanf(f, " %d", &val) != 1) {
            fprintf(stderr, "Unexpected EOF in %s at line %d\n", path, i);
            fclose(f);
            exit(1);
        }
    }
    fclose(f);
    return val;
}

// Read N*N complex values from a flat text file (interleaved re im per element)
// Each call occupies N*N lines in the file (call_idx selects the block)
static void read_complex_matrix(const char *dir, const char *fname,
                                int call_idx,
                                complex_t mat[N][N])
{
    char path[512];
    make_path(path, sizeof(path), dir, fname);
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }

    int total_elements = N * N; // per call
    int skip = call_idx * total_elements;
    double re_d, im_d;

    // Skip previous calls
    for (int s = 0; s < skip; s++) {
        if (fscanf(f, " %lf %lf", &re_d, &im_d) != 2) {
            fprintf(stderr, "Unexpected EOF skipping in %s\n", path);
            fclose(f);
            exit(1);
        }
    }

    // Read this call
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (fscanf(f, " %lf %lf", &re_d, &im_d) != 2) {
                fprintf(stderr, "Unexpected EOF reading [%d][%d] in %s\n",
                        i, j, path);
                fclose(f);
                exit(1);
            }
            mat[i][j].re = (fixed_t)re_d;
            mat[i][j].im = (fixed_t)im_d;
        }
    }
    fclose(f);
}

// ---------------------------------------------------------------------------
// Write helpers
// ---------------------------------------------------------------------------

static void write_int_scalar(const char *dir, const char *fname, int val)
{
    char path[512];
    make_path(path, sizeof(path), dir, fname);
    FILE *f = fopen(path, "w");
    if (!f) { fprintf(stderr, "Cannot open %s for writing\n", path); exit(1); }
    fprintf(f, "%d\n", val);
    fclose(f);
}

static void write_complex_vector(const char *dir, const char *fname,
                                 complex_t vec[N])
{
    char path[512];
    make_path(path, sizeof(path), dir, fname);
    FILE *f = fopen(path, "w");
    if (!f) { fprintf(stderr, "Cannot open %s for writing\n", path); exit(1); }
    for (int i = 0; i < N; i++) {
        fprintf(f, "%.17g %.17g\n",
                (double)vec[i].re, (double)vec[i].im);
    }
    fclose(f);
}

static void write_complex_matrix(const char *dir, const char *fname,
                                 complex_t mat[N][N])
{
    char path[512];
    make_path(path, sizeof(path), dir, fname);
    FILE *f = fopen(path, "w");
    if (!f) { fprintf(stderr, "Cannot open %s for writing\n", path); exit(1); }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            fprintf(f, "%.17g %.17g\n",
                    (double)mat[i][j].re, (double)mat[i][j].im);
        }
    }
    fclose(f);
}

// ---------------------------------------------------------------------------
// Main: run call index 0 only
// ---------------------------------------------------------------------------
int main()
{
    static complex_t A_in[N][N];
    int max_iter_in;

    // --- Read inputs (call index 0) ---
    read_complex_matrix(IO_DIR, "in_A.txt", 0, A_in);
    max_iter_in = read_int_scalar(IO_DIR, "in_max_iter.txt", 0);

    // --- Allocate outputs ---
    static complex_t out_eig[N];
    static complex_t out_V[N][N];
    int out_iter = 0;

    // --- Call kernel ---
    kernel_top(A_in, max_iter_in, &out_iter, out_eig, out_V);

    // --- Write outputs ---
    write_int_scalar(SIM_DIR, "out_0.txt", out_iter);
    write_complex_vector(SIM_DIR, "out_1.txt", out_eig);
    write_complex_matrix(SIM_DIR, "out_2.txt", out_V);

    printf("kernel_top done. iter=%d\n", out_iter);
    return 0;
}
